162	// rendered is a manifest stream decoded document by document.
163	type rendered struct {
164		raw   []byte
165		nodes []*yaml.Node // the content of each document, in stream order
166		kinds []string
167	}
168	
169	// decodeStream splits a multi-document stream and decodes each document. A
170	// stream that does not decode, or that holds an empty document, fails the test.
171	func decodeStream(t *testing.T, raw []byte) rendered {
172		t.Helper()
173		r := rendered{raw: raw}
174		dec := yaml.NewDecoder(bytes.NewReader(raw))
175		for i := 0; ; i++ {
176			var doc yaml.Node
177			err := dec.Decode(&doc)
178			if err == io.EOF {
179				break
180			}
181			if err != nil {
182				t.Fatalf("document %d does not decode: %v\n%s", i, err, raw)
183			}
184			if len(doc.Content) == 0 || doc.Content[0].Kind != yaml.MappingNode {
185				t.Fatalf("document %d is empty or is not a mapping", i)
186			}
187			var o object
188			if err := doc.Content[0].Decode(&o); err != nil {
189				t.Fatalf("document %d: %v", i, err)
190			}
191			r.nodes = append(r.nodes, doc.Content[0])
192			r.kinds = append(r.kinds, o.Kind)
193		}
194		return r
195	}
196	
197	// of decodes the only document of the given kind into out and returns its index.
198	func (r rendered) of(t *testing.T, kind string, out any) {
199		t.Helper()
200		found := -1
201		for i, k := range r.kinds {
202			if k == kind {
203				if found >= 0 {
204					t.Fatalf("two documents of kind %s", kind)
205				}
206				found = i
207			}
208		}
209		if found < 0 {
210			t.Fatalf("no document of kind %s in %v", kind, r.kinds)
211		}
212		if err := r.nodes[found].Decode(out); err != nil {
213			t.Fatalf("decode %s: %v", kind, err)
214		}
215	}
