245	func mustRender(t *testing.T, p Params) rendered {
246		t.Helper()
247		if err := p.Validate(); err != nil {
248			t.Fatalf("the test params are not valid: %v", err)
249		}
250		raw, err := Render(p)
251		if err != nil {
252			t.Fatalf("Render: %v", err)
253		}
254		return decodeStream(t, raw)
255	}
