257	// customParams moves every value the manifests carry away from its default.
258	func customParams() Params {
259		p := Defaults()
260		p.Namespace = "nexus-bench-2"
261		p.HTTPNodePort = 30581
262		p.DockerNodePort = 30582
263		p.Image = "registry.example.com/team/nexus3"
264		p.ImageTag = "3.99.0"
265		p.CPURequest = "750m"
266		p.CPULimit = "1500m"
267		p.MemoryRequest = "2560Mi"
268		p.MemoryLimit = "5Gi"
269		p.StorageSize = "7Gi"
270		p.JVMOpts = "-Xms512m -Xmx512m -XX:MaxDirectMemorySize=768m"
271		return p
272	}
