300	func TestRenderIsDeterministic(t *testing.T) {
301		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
302			t.Run(name, func(t *testing.T) {
303				first, err := Render(p)
304				if err != nil {
305					t.Fatal(err)
306				}
307				for i := 0; i < 5; i++ {
308					again, err := Render(p)
309					if err != nil {
310						t.Fatal(err)
311					}
312					if !bytes.Equal(first, again) {
313						t.Fatalf("render %d differs from the first one", i+2)
314					}
315				}
316			})
317		}
318	}
