410	func TestRenderNamespaceLabels(t *testing.T) {
411		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
412			t.Run(name, func(t *testing.T) {
413				ns := mustRender(t, p).namespace(t)
414				for key, want := range map[string]string{labelManagedBy: benchLabel, labelPartOf: benchLabel} {
415					if got := ns.Metadata.Labels[key]; got != want {
416						t.Errorf("label %s = %q, want %q", key, got, want)
417					}
418				}
419				for key := range ns.Metadata.Labels {
420					if strings.HasPrefix(key, psaPrefix) {
421						t.Errorf("the Namespace carries the Pod Security label %s: the bench never sets one", key)
422					}
423				}
424			})
425		}
426	}
