438	func TestRenderNothingSensitive(t *testing.T) {
439		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
440			t.Run(name, func(t *testing.T) {
441				r := mustRender(t, p)
442				lower := strings.ToLower(string(r.raw))
443				for _, word := range []string{"password", "secret"} {
444					if i := strings.Index(lower, word); i >= 0 {
445						t.Errorf("the render holds %q: ...%s...", word, r.raw[max(0, i-40):min(len(r.raw), i+40)])
446					}
447				}
448				for _, kind := range r.kinds {
449					if kind == "Secret" || kind == "ConfigMap" {
450						t.Errorf("the render holds a %s", kind)
451					}
452				}
453				d := r.deployment(t)
454				for _, v := range d.Spec.Template.Spec.Volumes {
455					if v.Secret != nil || v.ConfigMap != nil || v.HostPath != nil {
456						t.Errorf("volume %s is a secret, a ConfigMap or a hostPath", v.Name)
457					}
458				}
459				for _, c := range allContainers(d) {
460					if len(c.EnvFrom) != 0 {
461						t.Errorf("container %s reads its environment from a source (envFrom)", c.Name)
462					}
463					for _, e := range c.Env {
464						if e.ValueFrom.Kind != 0 {
465							t.Errorf("container %s: env %s comes from valueFrom", c.Name, e.Name)
466						}
467					}
468				}
469			})
470		}
471	}
