478	func TestRenderPVC(t *testing.T) {
479		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
480			t.Run(name, func(t *testing.T) {
481				pvc := mustRender(t, p).pvc(t)
482				if !reflect.DeepEqual(pvc.Spec.AccessModes, []string{"ReadWriteOnce"}) {
483					t.Errorf("accessModes = %v, want [ReadWriteOnce]", pvc.Spec.AccessModes)
484				}
485				if got := pvc.Spec.Resources.Requests["storage"]; got != p.StorageSize {
486					t.Errorf("storage request = %q, want %q", got, p.StorageSize)
487				}
488				if pvc.Spec.StorageClassName != nil {
489					t.Errorf("storageClassName = %q, want it absent so the cluster default class applies", *pvc.Spec.StorageClassName)
490				}
491				if pvc.Spec.VolumeName != "" {
492					t.Errorf("volumeName = %q, want it absent: the bench binds to no existing volume", pvc.Spec.VolumeName)
493				}
494			})
495		}
496	}
