709	// resolvePort turns a probe or Service port, a number or a container port name,
710	// into the number; 0 when it names no port of the container.
711	func resolvePort(n yaml.Node, c container) int {
712		if v, err := strconv.Atoi(n.Value); err == nil {
713			return v
714		}
715		for _, p := range c.Ports {
716			if p.Name == n.Value {
717				return p.ContainerPort
718			}
719		}
720		return 0
721	}
