897	func TestRenderRefusesInvalidParams(t *testing.T) {
898		cases := []struct {
899			name   string
900			mutate func(p *Params)
901			wantIn string // a variable name Validate reports, proving the error comes from it
902		}{
903			{"reserved namespace", func(p *Params) { p.Namespace = "default" }, "NEXUS_BENCH_NAMESPACE"},
904			{"kube namespace", func(p *Params) { p.Namespace = "kube-system" }, "NEXUS_BENCH_NAMESPACE"},
905			{"namespace with an upper-case letter", func(p *Params) { p.Namespace = "Bench" }, "NEXUS_BENCH_NAMESPACE"},
906			{"empty namespace", func(p *Params) { p.Namespace = "" }, "NEXUS_BENCH_NAMESPACE"},
907			{"namespace that injects a key", func(p *Params) { p.Namespace = "a\nkind: Secret" }, "NEXUS_BENCH_NAMESPACE"},
908			{"same NodePort twice", func(p *Params) { p.DockerNodePort = p.HTTPNodePort }, "NEXUS_BENCH_HTTP_NODEPORT"},
909			{"NodePort out of range", func(p *Params) { p.HTTPNodePort = 8081 }, "NEXUS_BENCH_HTTP_NODEPORT"},
910			{"image from the zot registry", func(p *Params) { p.Image = "tvp-zot.incus:5000/nexus3" }, "NEXUS_BENCH_IMAGE"},
911			{"image tag with a space", func(p *Params) { p.ImageTag = "3.98 1" }, "NEXUS_BENCH_IMAGE_TAG"},
912			{"empty JVM options", func(p *Params) { p.JVMOpts = "" }, "NEXUS_BENCH_JVM_OPTS"},
913			{"JVM options with a newline", func(p *Params) { p.JVMOpts = "-Xmx1g\n  - name: x" }, "NEXUS_BENCH_JVM_OPTS"},
914			{"JVM options with a quote", func(p *Params) { p.JVMOpts = `-Dx="a"` }, "NEXUS_BENCH_JVM_OPTS"},
915			{"JVM options holding a colon and a space", func(p *Params) { p.JVMOpts = "-Dx: y" }, "NEXUS_BENCH_JVM_OPTS"},
916			{"CPU request above its limit", func(p *Params) { p.CPURequest = "3" }, "NEXUS_BENCH_CPU_REQUEST"},
917			{"memory that is not a quantity", func(p *Params) { p.MemoryLimit = "lots" }, "NEXUS_BENCH_MEMORY_LIMIT"},
918			{"zero storage", func(p *Params) { p.StorageSize = "0Gi" }, "NEXUS_BENCH_STORAGE_SIZE"},
919		}
920		for _, tc := range cases {
921			t.Run(tc.name, func(t *testing.T) {
922				p := Defaults()
923				tc.mutate(&p)
924				if p.Validate() == nil {
925					t.Fatal("the test case is meant to be invalid but Validate accepts it")
926				}
927	
928				raw, err := Render(p)
929				if err == nil {
930					t.Fatalf("Render accepted invalid params and wrote:\n%s", raw)
931				}
932				if !strings.Contains(err.Error(), tc.wantIn) {
933					t.Errorf("Render error = %q, want it to carry Validate's message naming %s", err, tc.wantIn)
934				}
935				if len(raw) != 0 {
936					t.Errorf("Render returned %d bytes next to an error, want none", len(raw))
937				}
938	
939				raw, err = RenderNamespace(p)
940				if err == nil {
941					t.Fatalf("RenderNamespace accepted invalid params and wrote:\n%s", raw)
942				}
943				if !strings.Contains(err.Error(), tc.wantIn) {
944					t.Errorf("RenderNamespace error = %q, want it to carry Validate's message naming %s", err, tc.wantIn)
945				}
946				if len(raw) != 0 {
947					t.Errorf("RenderNamespace returned %d bytes next to an error, want none", len(raw))
948				}
949			})
950		}
951	}
